import React, { useState } from 'react';
import { createUser, createOrder } from '../utils/api';
import { formatCurrency } from '../utils/helpers';
import './CheckoutForm.css';

export default function CheckoutForm({ cartItems = [], onOrderPlaced }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');
  const [showPopup, setShowPopup] = useState(false);

  // ✅ Validate form fields
  const validate = () => {
    const newErrors = {};
    if (!name.trim()) newErrors.name = 'Name is required';
    if (!email.trim()) newErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(email))
      newErrors.email = 'Please enter a valid email address';
    if (!password.trim()) newErrors.password = 'Password is required';
    else if (password.length < 6)
      newErrors.password = 'Password must be at least 6 characters';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const totalAmount = cartItems.reduce(
    (sum, item) => sum + (Number(item.price) || 0) * (Number(item.quantity) || 0),
    0
  );

  const handleSubmit = async (e) => {
    e.preventDefault();
    setApiError('');
    if (!validate()) return;

    try {
      // 1️⃣ Create user
      const user = await createUser({ name, email, password });

      // 2️⃣ Build order items
      const orderItems = cartItems.map((item) => ({
        quantity: item.quantity,
        subtotal: item.price * item.quantity,
        product: { id: item.id },
      }));

      // 3️⃣ Place order with userId
      const order = await createOrder({
        userId: user.id,
        orderItems,
        totalAmount,
      });

      onOrderPlaced && onOrderPlaced(order);

      // 4️⃣ Reset form
      setName('');
      setEmail('');
      setPassword('');
      setErrors({});
      setApiError('');
      setShowPopup(true);

    } catch (err) {
      const message =
        (err && err.response && err.response.data && err.response.data.message) ||
        err.message ||
        'Failed to place order';
      setApiError(message);
    }
  };

  return (
    <div className="checkout-container">
      <h2>Checkout</h2>
      <form onSubmit={handleSubmit} className="checkout-form">
        <div className="form-group">
          <label>Name</label>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            className={errors.name ? 'error' : ''}
            placeholder="Name"
          />
          {errors.name && <div className="error-message">{errors.name}</div>}
        </div>

        <div className="form-group">
          <label>Email</label>
          <input
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className={errors.email ? 'error' : ''}
            placeholder="Email"
          />
          {errors.email && <div className="error-message">{errors.email}</div>}
        </div>

        <div className="form-group">
          <label>Password</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className={errors.password ? 'error' : ''}
            placeholder="Password"
          />
          {errors.password && <div className="error-message">{errors.password}</div>}
        </div>

        <button type="submit" disabled={cartItems.length === 0}>
          Place Order
        </button>
        {apiError && <div className="api-error">{apiError}</div>}
      </form>

      <div className="order-summary">
        <h3>Order Summary</h3>
        {cartItems.length === 0 ? (
          <div>No items in cart</div>
        ) : (
          cartItems.map((item) => (
            <div key={item.id} className="summary-item">
              {item.name} x {item.quantity} - {formatCurrency(item.price * item.quantity)}
            </div>
          ))
        )}
        <div><strong>Total: {formatCurrency(totalAmount)}</strong></div>
      </div>

      {showPopup && (
        <div className="popup-overlay">
          <div className="popup">
            <h3>✅ Checkout Successful!</h3>
            <p>Your order has been placed successfully.</p>
            <button onClick={() => setShowPopup(false)}>OK</button>
          </div>
        </div>
      )}
    </div>
  );
}
